document.getElementById('gen-btn').addEventListener('click', async () => {
  const topic = document.getElementById('topic').value;
  const output = document.getElementById('lesson-result');
  const loader = document.getElementById('loading');

  if (!topic) {
    alert('Please enter a topic!');
    return;
  }

  loader.classList.remove('hidden');
  output.innerText = '';

  try {
    const prompt = `Create a Grade 6 bilingual lesson plan (English and Spanish) about Urban Ecosystems focusing on ${topic}. 
    Include: 
    1. Learning Objectives.
    2. Key Vocabulary.
    3. A step-by-step activity.
    4. A brief assessment.
    Format it clearly using Markdown.`;

    const result = await generateText(prompt);
    output.innerText = result;
  } catch (e) {
    output.innerText = 'Error generating lesson: ' + e.message;
  } finally {
    loader.classList.set('hidden', true); // Note: should be classList.add('hidden')
    loader.classList.add('hidden');
  }
});

