(function() {
  const btn = document.getElementById("rollBtn");
  const out = document.getElementById("outEl");
  const initialText = out.innerText;

  btn.click();
  const firstRoll = out.innerText;

  btn.click();
  const secondRoll = out.innerText;

  return {
    clicked: true,
    changed: firstRoll !== initialText,
    randomized: firstRoll !== secondRoll,
    currentValue: firstRoll
  };
})()

(function() {
  const btn = document.getElementById("rollBtn");
  const out = document.getElementById("outEl");
  if (!btn || !out) return "Missing elements";

  // Test 1: Initial state
  const initialText = out.innerText;

  // Test 2: First click
  btn.click();
  const firstRoll = out.innerText;

  // Test 3: Second click (randomness check)
  btn.click();
  const secondRoll = out.innerText;

  return {
    initialText,
    firstRoll,
    secondRoll,
    changed: firstRoll !== initialText,
    randomized: firstRoll !== secondRoll,
    result: (firstRoll !== initialText && firstRoll !== secondRoll) ? "PASS" : "FAIL"
  };
})()

(function() {
  const out = document.getElementById("outEl");
  const text = out.innerText.trim();
  return {
    hasInitialValue: text.length > 0,
    value: text
  };
})()

(function() {
  const btn = document.getElementById("rollBtn");
  const out = document.getElementById("outEl");
  const results = [];

  try {
    for(let i = 0; i < 10; i++) {
      btn.click();
      results.push(out.innerText);
    }
  } catch (e) {
    return "Crash during rapid fire: " + e.message;
  }

  const unique = new Set(results).size;
  return {
    rolls: results.length,
    uniqueResults: unique,
    success: unique > 1,
    details: results
  };
})()

(function() {
  const btn = document.getElementById("rollBtn");
  const out = document.getElementById("outEl");
  const samples = [];

  for(let i = 0; i < 20; i++) {
    btn.click();
    const text = out.innerText.trim();
    samples.push(text);
    if (text === "") return "CRITICAL: Generator produced an empty string";
  }

  const uniqueCount = new Set(samples).size;
  return {
    totalSamples: samples.length,
    uniqueCount: uniqueCount,
    diversityScore: (uniqueCount / samples.length * 100).toFixed(2) + "%",
    status: "PASS"
  };
})()

(function() {
  const out = document.getElementById("outEl");
  const text = out.innerText.trim();
  return {
    initialValuePresent: text.length > 0,
    value: text
  };
})()

(function() {
  const btn = document.getElementById("rollBtn");
  const out = document.getElementById("outEl");

  // Test 1: Verify content changes on every single click (no caching issues)
  btn.click();
  const val1 = out.innerText;
  btn.click();
  const val2 = out.innerText;

  // Test 2: Check for common failure patterns (undefined, null, [object Object])
  const failures = ["undefined", "null", "[object Object]", "NaN"];
  const hasFailure = failures.some(f => val2.includes(f));

  return {
    changed: val1 !== val2,
    val1: val1,
    val2: val2,
    hasFailure: hasFailure,
    status: (val1 !== val2 && !hasFailure) ? "PASS" : "FAIL"
  };
})()

(function() {
  const btn = document.getElementById("rollBtn");
  const out = document.getElementById("outEl");

  const textBefore = out.innerText;
  btn.click();
  const textAfter = out.innerText;

  return {
    changed: textBefore !== textAfter,
    before: textBefore,
    after: textAfter,
    status: (textBefore !== textAfter) ? "PASS" : "FAIL"
  };
})()

(function() {
  const btn = document.getElementById("rollBtn");
  const out = document.getElementById("outEl");
  const results = [];

  // Trigger 5 rapid rolls
  for(let i = 0; i < 5; i++) {
    btn.click();
    results.push(out.innerText);
  }

  const allUnique = new Set(results).size === results.length;

  return {
    rolls: results,
    allUnique: allUnique,
    status: allUnique ? "PASS" : "POTENTIAL COLLISION/SPOOF"
  };
})()

(function() {
  const btn = document.getElementById("rollBtn");
  const out = document.getElementById("outEl");

  // Capture initial state
  const initialText = out.innerText;

  // Trigger roll
  btn.click();
  const afterFirstRoll = out.innerText;

  // Verify replacement (not appending)
  const isAppending = afterFirstRoll.includes(initialText) && afterFirstRoll !== initialText;

  // Trigger second roll
  btn.click();
  const afterSecondRoll = out.innerText;

  return {
    initial: initialText,
    first: afterFirstRoll,
    second: afterSecondRoll,
    isAppending: isAppending,
    changedAgain: afterFirstRoll !== afterSecondRoll,
    status: (!isAppending && afterFirstRoll !== initialText && afterSecondRoll !== afterFirstRoll) ? "PASS" : "FAIL"
  };
})()

(function() {
  const btn = document.getElementById("rollBtn");
  const out = document.getElementById("outEl");
  const samples = new Set();

  for(let i = 0; i < 20; i++) {
    btn.click();
    samples.add(out.innerText);
  }

  return {
    total_rolls: 20,
    unique_results: samples.size,
    diversity_score: (samples.size / 20) * 100 + "%",
    status: samples.size > 15 ? "PASS" : "LOW DIVERSITY"
  };
})()

(function() {
  const btn = document.getElementById("rollBtn");
  const out = document.getElementById("outEl");
  const results = [];

  for(let i = 0; i < 10; i++) {
    btn.click();
    results.push(out.innerText);
  }

  const unique = new Set(results).size;
  return {
    sampleSize: 10,
    uniqueCount: unique,
    diversity: (unique/10)*100 + "%",
    allUnique: unique === 10,
    status: unique > 8 ? "PASS" : "LOW DIVERSITY"
  };
})()

(function() {
  const out = document.getElementById("outEl");
  const btn = document.getElementById("rollBtn");

  // Test initial state: is it empty or does it have a default?
  const initialState = out.innerText;

  // Test for potential null/undefined leaks in the output
  btn.click();
  const firstRoll = out.innerText;

  return {
    initialState: initialState,
    firstRoll: firstRoll,
    isFunctional: (firstRoll !== "" && firstRoll !== "undefined" && firstRoll !== "null"),
    elementCheck: {
      rollBtn: !!btn,
      outEl: !!out
    }
  };
})()

