let currentRoomIdx = 0;
let currentLang = 'en';

function renderRoom() {
    const room = rooms[currentRoomIdx];
    const container = document.getElementById('app');

    let html = `<div class="room-container">
        <h1>${room.title[currentLang]}</h1>`;

    if (room.type === 'vocab') {
        html += `<p>${room.content[currentLang]}</p>
        <ul class="vocab-list">
            ${room.vocab.map(item => `<li><strong>${item.en}</strong>: ${item.vi}</li>`).join('')}
        </ul>`;
    } else if (room.type === 'quiz') {
        html += `<p>${room.question[currentLang]}</p>
        <div class="choices">
            ${room.choices.map((choice, idx) => `<button onclick="checkAnswer(${idx})">${choice.text[currentLang]}</button>`).join('')}
        </div>`;
    } else if (room.type === 'summary') {
        html += `<p>${room.summary[currentLang]}</p>`;
    }

    html += `<div class="nav">
        <button onclick="prevRoom()" ${currentRoomIdx === 0 ? 'disabled' : ''}>Back</button>
        <button onclick="nextRoom()" ${currentRoomIdx === rooms.length - 1 ? 'disabled' : ''}>Next</button>
    </div></div>`;

    container.innerHTML = html;
}

function nextRoom() {
    if (currentRoomIdx < rooms.length - 1) {
        currentRoomIdx++;
        renderRoom();
    }
}

function prevRoom() {
    if (currentRoomIdx > 0) {
        currentRoomIdx--;
        renderRoom();
    }
}

function checkAnswer(idx) {
    const room = rooms[currentRoomIdx];
    if (room.choices[idx].correct) {
        alert('Correct!');
        nextRoom();
    } else {
        alert('Try again!');
    }
}

