function handleChoice(btn) {
    const room = rooms[state.roomIndex];
    const feedbackEl = document.getElementById('room-feedback');
    feedbackEl.innerText = btn.dataset.answer === 'true' ? room.feedback.correct : room.feedback.wrong;
    feedbackEl.classList.remove('hidden');
    if(btn.dataset.answer === 'true') state.score++;
    updateUI();
}

function updateUI() {
    const room = rooms[state.roomIndex];
    document.getElementById('room-title').innerText = room.title;
    document.getElementById('room-description').innerText = room.description;
    const optionsContainer = document.getElementById('options-container');
    optionsContainer.innerHTML = '';
    room.options.forEach(opt => {
        const btn = document.createElement('button');
        btn.innerText = opt.text;
        btn.dataset.answer = opt.correct;
        btn.onclick = () => handleChoice(btn);
        optionsContainer.appendChild(btn);
    });
    document.getElementById('score-display').innerText = `Score: ${state.score}`;
}

